 o.org_name AS 机构名称, d.data_date AS 日期, d.index_value AS `各项存款余额(亿元)` FROM index_data d JOIN org_info o ON d.org_code = o.org_code WHERE o.org_name = \'江苏省B市农商行\' AND d.index_name = \'各项存款余额\' AND d.data_date = \'2025-12-31\'',NULL,NULL,'2026-08-05 12:38:04','[]',1),(86,'123','江苏省A市农商行在2025年12月31日的各项存款余额、各项贷款余额、净利润分别是多少？请用柱状图展示。','SELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    d.index_name AS 指标名称,\n    d.index_value AS 指标值\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\nWHERE o.org_name = \'江苏省A市农商行\'\n  AND d.data_date = \'2025-12-31\'\n  AND d.index_name IN (\'各项存款余额\', \'各项贷款余额\', \'净利润\')\nORDER BY d.index_name;',NULL,NULL,'2026-08-05 12:38:30','[{\"日期\": \"2025-12-31\", \"指标值\": \"81.4600\", \"指标名称\": \"净利润\", \"机构名称\": \"江苏省A市农商行\"}, {\"日期\": \"2025-12-31\", \"指标值\": \"42.2500\", \"指标名称\": \"各项存款余额\", \"机构名称\": \"江苏省A市农商行\"}, {\"日期\": \"2025-12-31\", \"指标值\": \"33.9500\", \"指标名称\": \"各项贷款余额\", \"机构名称\": \"江苏省A市农商行\"}]',0),(87,'123','江苏省A市农商行在2025年12月31日的对公存款和个人存款分别占各项存款的比例？请用饼图展示','SELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    \'对公存款占比\' AS 指标名称,\n    ROUND(\n        SUM(CASE WHEN d.index_name = \'对公存款余额\' THEN d.index_value ELSE 0 END) \n        / NULLIF(SUM(CASE WHEN d.index_name = \'各项存款余额\' THEN d.index_value ELSE 0 END), 0) * 100, \n        2\n    ) AS `指标值(%)`,\n    il.index_unit AS 单位\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\nJOIN index_list il ON il.index_name = \'对公存款余额\'\nWHERE o.org_name = \'江苏省A市农商行\'\n  AND d.data_date = \'2025-12-31\'\n  AND d.index_name IN (\'对公存款余额\', \'个人存款余额\', \'各项存款余额\')\nGROUP BY o.org_name, d.data_date, il.index_unit\n\nUNION ALL\n\nSELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    \'个人存款占比\' AS 指标名称,\n    ROUND(\n        SUM(CASE WHEN d.index_name = \'个人存款余额\' THEN d.index_value ELSE 0 END) \n        / NULLIF(SUM(CASE WHEN d.index_name = \'各项存款余额\' THEN d.index_value ELSE 0 END), 0) * 100, \n        2\n    ) AS `指标值(%)`,\n    il.index_unit AS 单位\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\nJOIN index_list il ON il.index_name = \'个人存款余额\'\nWHERE o.org_name = \'江苏省A市农商行\'\n  AND d.data_date = \'2025-12-31\'\n  AND d.index_name IN (\'对公存款余额\', \'个人存款余额\', \'各项存款余额\')\nGROUP BY o.org_name, d.data_date, il.index_unit;',NULL,NULL,'2026-08-05 12:39:12','[{\"单位\": \"亿元\", \"日期\": \"2025-12-31\", \"指标值(%)\": \"35.03\", \"指标名称\": \"对公存款占比\", \"机构名称\": \"江苏省A市农商行\"}, {\"单位\": \"亿元\", \"日期\": \"2025-12-31\", \"指标值(%)\": \"64.95\", \"指标名称\": \"个人存款占比\", \"机构名称\": \"江苏省A市农商行\"}]',0),(88,'123','A市分行在2025.12.31的各项存款余额是多少？','SELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    d.index_value AS `各项存款余额(亿元)`\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\nWHERE o.org_name = \'A市分行\'\n  AND d.index_name = \'各项存款余额\'\n  AND d.data_date = \'2025-12-31\';',NULL,NULL,'2026-08-05 12:47:57','[]',0),(89,'123','A市农商行在2025年12月31日各项存款余额是多少？','SELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    d.index_value AS `各项存款余额(亿元)`\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\nWHERE o.org_name = \'江苏省A市农商行\'\n  AND d.index_name = \'各项存款余额\'\n  AND d.data_date = \'2025-12-31\'',NULL,NULL,'2026-08-05 12:48:40','[{\"日期\": \"2025-12-31\", \"机构名称\": \"江苏省A市农商行\", \"各项存款余额(亿元)\": \"42.2500\"}]',0),(90,'123','A市农商行在2024年12月31日各项存款余额是多少？','SELECT o.org_name AS 机构名称, d.data_date AS 日期, d.index_value AS `各项存款余额(亿元)`, i.index_unit AS 单位 FROM index_data d JOIN org_info o ON d.org_code = o.org_code JOIN index_list i ON d.index_name = i.index_name WHERE o.org_name = \'江苏省A市农商行\' AND d.index_name = \'各项存款余额\' AND d.data_date = \'2024-12-31\'',NULL,NULL,'2026-08-05 12:49:58','[{\"单位\": \"亿元\", \"日期\": \"2024-12-31\", \"机构名称\": \"江苏省A市农商行\", \"各项存款余额(亿元)\": \"41.7600\"}]',0),(91,'123','A市分行在2024年12月31日各项存款余额是多少？','SELECT \n    o.org_name AS 机构名称,\n    d.data_date AS 日期,\n    d.index_value AS `各项存款余额(亿元)`,\n    \'亿元\' AS 单位\nFROM index_data d\nJOIN org_info o ON d.org_code = o.org_code\